class Solution {
    public int maxSubArray(int[] nums) {
        int current = nums[0];
        int best = nums[0];
        for (int index = 1; index < nums.length; index++) {
            current = Math.max(nums[index], current + nums[index]);
            best = Math.max(best, current);
        }
        return best;
    }
}
